<script setup lang="ts">
import {computed} from 'vue'
import type {Trip} from '@/types'
const props=defineProps<{trip:Trip;days:number;activities:number;busy:boolean}>()
const emit=defineEmits<{edit:[];photos:[]}>()
const date=(value:string)=>new Date(value+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})
const duration=computed(()=>props.trip.start_date?Math.round((Date.parse(props.trip.end_date||props.trip.start_date)-Date.parse(props.trip.start_date))/86400000)+1:null)
</script>
<template><header class="journey-cover" :class="{'has-photo':trip.cover_image_path}"><div class="cover-copy"><p class="cover-kicker"><span aria-hidden="true">↗</span> Your personal itinerary</p><h1>{{trip.title}}</h1><p class="cover-destination">{{trip.destination||'A destination to discover'}}</p><div class="cover-facts"><span>{{trip.start_date?date(trip.start_date):'Flexible dates'}}<template v-if="trip.end_date&&trip.end_date!==trip.start_date"> — {{date(trip.end_date)}}</template></span><span v-if="duration">{{duration}} {{duration===1?'day':'days'}}</span><span>{{activities}} {{activities===1?'activity':'activities'}}</span></div><div class="cover-actions"><button :disabled="busy" @click="emit('edit')">Edit trip details</button><button :disabled="busy" aria-label="Manage trip photographs" @click="emit('photos')">{{trip.cover_image_path?'Change cover':'Add a cover photo'}}</button></div></div><img v-if="trip.cover_image_path" class="cover-photo" :src="trip.cover_image_path" :alt="trip.destination||trip.title" /><div v-else class="cover-stamp" aria-hidden="true"><span>CRONEVIA</span><strong>{{String(days).padStart(2,'0')}}</strong><span>days to make yours</span><i>✧</i></div></header></template>
<style scoped>.journey-cover{display:grid;grid-template-columns:minmax(0,1fr) 180px;border:1px solid #d7ccba;border-radius:14px;background:#faf6ed;overflow:hidden;margin-bottom:20px;position:relative}.cover-copy{padding:24px 28px;min-width:0;border-left:5px solid #74283c}.cover-kicker{font-size:10px;letter-spacing:.15em;text-transform:uppercase;color:#778267;display:flex;gap:10px;align-items:center}.cover-kicker span{font-size:20px}.journey-cover h1{font-size:clamp(28px,3.2vw,42px);line-height:1.08;margin:8px 0 10px;max-width:800px}.cover-destination{font-size:16px;color:#6e775f;overflow-wrap:anywhere}.cover-facts{display:flex;flex-wrap:wrap;gap:8px 16px;font-size:13px;color:#766b5c;margin:14px 0}.cover-facts span+span{border-left:1px solid #d5cab8;padding-left:16px}.cover-actions{display:flex;gap:8px;flex-wrap:wrap}.cover-actions button{font-size:13px}.cover-photo{height:100%;min-height:220px;width:100%;object-fit:cover}.cover-stamp{margin:22px;align-self:center;border:1px dashed #98a185;border-radius:50%;aspect-ratio:1;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#7b886d;transform:rotate(8deg);font-size:10px;text-align:center;gap:6px}.cover-stamp>span:first-child{letter-spacing:.17em}.cover-stamp strong{font:italic 44px Georgia}.cover-stamp i{font-style:normal;font-size:20px}.has-photo{grid-template-columns:minmax(0,1fr) 30%}@media(max-width:699px){.journey-cover,.has-photo{grid-template-columns:minmax(0,1fr)}.cover-copy{padding:16px}.cover-stamp{display:none}.cover-photo{height:112px;min-height:0;grid-row:1}.cover-facts{gap:8px;font-size:12px}.cover-facts span+span{padding-left:8px}.journey-cover h1{font-size:29px}.cover-actions button{flex:1}.cover-kicker{font-size:9px}.cover-destination{font-size:14px}}</style>
